def find_golomb_ruler(n, max_len):
    # We know the first mark is 0.
    # We can search for the marks in increasing order.
    # This is a simple backtracking search.

    def backtrack(current_marks, last_mark):
        if len(current_marks) == n:
            return current_marks

        for next_mark in range(last_mark + 1, max_len + 1):
            new_marks = current_marks + [next_mark]
            # Check if new_marks is a valid partial Golomb ruler
            if is_golomb(new_marks):
                result = backtrack(new_marks, next_mark)
                if result:
                    return result
        return None

    return backtrack([0], 0)

